import{_ as p,o as i,c as l,a2 as e}from"./chunks/framework.DGk0zlJw.js";const u=JSON.parse('{"title":"Beacon — 产品与技术实施总方案","description":"","frontmatter":{},"headers":[],"relativePath":"zh/master-plan.md","filePath":"zh/master-plan.md"}'),n={name:"zh/master-plan.md"};function s(t,a,o,r,d,c){return i(),l("div",null,[...a[0]||(a[0]=[e(`<h1 id="beacon-—-产品与技术实施总方案" tabindex="-1">Beacon — 产品与技术实施总方案 <a class="header-anchor" href="#beacon-—-产品与技术实施总方案" aria-label="Permalink to &quot;Beacon — 产品与技术实施总方案&quot;">​</a></h1><blockquote><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>状态</td><td><strong>产品范围与设计基线</strong>（2026-10-11 用户定版收编）</td></tr><tr><td>上游</td><td><a href="./mission.html">任务书</a> · <a href="./positioning.html">定位</a></td></tr><tr><td>关系</td><td>与 <a href="./rfc/RFC-001-technical-design.html">RFC-001</a> 并行的产品基线；冲突处以本文档「差异审计」（mvp-issues 批3-补26）与用户拍板为准</td></tr><tr><td>术语对照</td><td><strong>已拍板（2026-10-11 批3-补27①）：RFC-001 编号为产品唯一口径</strong>（L0=钉选悬浮组件 / L1=胶囊 / L2=Quick Panel / L3=详情）；本文档 §3 的 L0/L1/L2 仅为原文行文，阅读映射：本文 L0=胶囊→RFC L1，本文 L1=面板→RFC L2，本文 L2=详情→RFC L3</td></tr></tbody></table></blockquote><hr><p><em>核心原则：Signal + Action，而不是 Dashboard + Automation。</em><em>版本：1.0 · 目标平台：Windows 10 / Windows 11 · 技术栈：C#、WinUI 3、.NET 10 · 仓库：<a href="https://github.com/cuihairu/beacon" target="_blank" rel="noreferrer">https://github.com/cuihairu/beacon</a></em></p><h2 id="_1-项目目标" tabindex="-1">1. 项目目标 <a class="header-anchor" href="#_1-项目目标" aria-label="Permalink to &quot;1. 项目目标&quot;">​</a></h2><h3 id="_1-1-产品定位" tabindex="-1">1.1 产品定位 <a class="header-anchor" href="#_1-1-产品定位" aria-label="Permalink to &quot;1.1 产品定位&quot;">​</a></h3><p>Beacon 是一个常驻 Windows 桌面的轻量开发者状态与操作中心。</p><p>它聚合开发者最需要关注的状态，在异常发生时提供提醒，并允许用户通过少量操作查看详情或执行简单操作。</p><p>Beacon 不替代 GitHub、CI/CD 平台或公司的打包工具，也不建设一套新的开发管理平台。</p><p>核心价值：</p><ol><li><p>不必反复切换窗口，就能知道重要任务的状态。</p></li><li><p>发生失败时，能够及时发现问题。</p></li><li><p>从通知到问题详情的路径尽可能短。</p></li><li><p>日常运行时占用空间小，不干扰正常开发。</p></li><li><p>不需要额外服务器、用户系统或云端服务。</p></li></ol><h3 id="_1-2-设计原则" tabindex="-1">1.2 设计原则 <a class="header-anchor" href="#_1-2-设计原则" aria-label="Permalink to &quot;1.2 设计原则&quot;">​</a></h3><ul><li><p><strong>Small by default</strong>：默认界面尽可能小。</p></li><li><p><strong>Signal over noise</strong>：只突出重要状态，不制造通知噪声。</p></li><li><p><strong>Local first</strong>：配置、状态缓存和必要的历史数据保存在本地。</p></li><li><p><strong>Provider-based</strong>：数据源通过统一接口接入。</p></li><li><p><strong>Native Windows experience</strong>：充分利用 Windows 原生窗口、托盘和通知能力。</p></li><li><p><strong>No reinvention</strong>：复杂操作直接跳转原始平台。</p></li><li><p><strong>Incremental delivery</strong>：先保证真实数据和桌面体验可靠，再扩展数据源。</p></li></ul><hr><h2 id="_2-功能范围" tabindex="-1">2. 功能范围 <a class="header-anchor" href="#_2-功能范围" aria-label="Permalink to &quot;2. 功能范围&quot;">​</a></h2><h3 id="_2-1-第一优先级-开发任务与-github" tabindex="-1">2.1 第一优先级：开发任务与 GitHub <a class="header-anchor" href="#_2-1-第一优先级-开发任务与-github" aria-label="Permalink to &quot;2.1 第一优先级：开发任务与 GitHub&quot;">​</a></h3><p><strong>开发任务状态</strong></p><p>首要目标是监控公司现有打包工具。</p><p>需要支持的能力由实际打包工具提供的数据决定：</p><ul><li><p>当前是否运行。</p></li><li><p>任务成功、失败、排队或取消。</p></li><li><p>任务开始时间和耗时。</p></li><li><p>最近一次成功或失败。</p></li><li><p>可获取的错误摘要。</p></li><li><p>打开原始任务详情。</p></li><li><p>在工具支持且权限允许时重试任务。</p></li></ul><p>Beacon 不负责实现打包逻辑，不负责构建编排，不重新实现打包工具的日志系统。</p><p>具体打包工具的 API、认证方式、状态字段和操作能力，需要在接入时根据实际接口确认。</p><p><strong>GitHub 状态</strong></p><ul><li><p>查看指定仓库的 GitHub Actions 最近运行状态。</p></li><li><p>查看关注的 Pull Request。</p></li><li><p>显示失败、运行中、成功等状态。</p></li><li><p>重要状态变化时通知。</p></li><li><p>打开 PR、Workflow Run 和原始日志。</p></li><li><p>在权限允许时重跑失败的 Workflow。</p></li></ul><p>GitHub Provider 继续使用现有实现，避免重复建设。</p><h3 id="_2-2-可选功能-ai-使用额度" tabindex="-1">2.2 可选功能：AI 使用额度 <a class="header-anchor" href="#_2-2-可选功能-ai-使用额度" aria-label="Permalink to &quot;2.2 可选功能：AI 使用额度&quot;">​</a></h3><p>AI 使用额度属于可选 Provider，不是 MVP 的阻塞条件。</p><p>仅在存在可靠数据来源时提供：</p><ul><li><p>当前可查询的使用额度。</p></li><li><p>重置时间。</p></li><li><p>数据更新时间。</p></li><li><p>接近阈值时的通知。</p></li></ul><p>如果无法获取官方或可靠的额度数据，明确显示未知或暂不支持。</p><p>不建设 AI 模型路由、API 代理、账号管理、模型调用面板或额度购买功能。</p><h3 id="_2-3-明确不做" tabindex="-1">2.3 明确不做 <a class="header-anchor" href="#_2-3-明确不做" aria-label="Permalink to &quot;2.3 明确不做&quot;">​</a></h3><p>以下内容不属于 Beacon 的产品目标：</p><ul><li><p>自定义脚本和命令执行平台。</p></li><li><p>通用任务调度或 Workflow Engine。</p></li><li><p>Docker、服务器和远程机器管理。</p></li><li><p>AI Agent 管理。</p></li><li><p>多设备控制中心或云同步。</p></li><li><p>第三方插件市场。</p></li><li><p>复杂图表和分析报表。</p></li><li><p>GitHub 的完整替代客户端。</p></li><li><p>通用监控平台。</p></li><li><p>账号注册、团队协作和独立后端。</p></li><li><p>多个独立桌面小组件组成的复杂桌面仪表盘。</p></li></ul><p>以上边界是长期产品约束，而不只是暂缓实现的事项。</p><hr><h2 id="_3-整体交互设计" tabindex="-1">3. 整体交互设计 <a class="header-anchor" href="#_3-整体交互设计" aria-label="Permalink to &quot;3. 整体交互设计&quot;">​</a></h2><p>Beacon 采用渐进式信息展示。</p><p>用户平时只看到小型状态入口；只有主动查看或出现重要异常时，才展开更多内容。</p><h3 id="_3-1-l0-桌面状态胶囊" tabindex="-1">3.1 L0：桌面状态胶囊 <a class="header-anchor" href="#_3-1-l0-桌面状态胶囊" aria-label="Permalink to &quot;3.1 L0：桌面状态胶囊&quot;">​</a></h3><p>这是 Beacon 最重要的视觉入口。</p><p>常驻屏幕右下角附近，用户可以移动位置，并在设置中调整显示行为。</p><p>建议展示：</p><ul><li><p>Beacon 状态指示。</p></li><li><p>当前是否存在需要关注的问题。</p></li><li><p>必要时显示异常数量。</p></li><li><p>点击打开悬浮面板。</p></li><li><p>右键打开托盘菜单或常用设置。</p></li></ul><p>默认状态不显示大量文字、图表或任务列表。</p><p>视觉状态：</p><table tabindex="0"><thead><tr><th>状态</th><th>表现</th></tr></thead><tbody><tr><td>正常</td><td>低干扰的中性色或成功状态</td></tr><tr><td>运行中</td><td>轻量运行指示</td></tr><tr><td>需要注意</td><td>黄色或其他警示状态</td></tr><tr><td>存在失败</td><td>明确的错误状态</td></tr><tr><td>数据源离线</td><td>灰色状态，同时保留最后更新时间</td></tr></tbody></table><p>颜色只是一种辅助信息，不能仅依赖颜色表达状态。图标、文字和可访问性标签也应传达含义。</p><p><strong>关键要求：胶囊不能抢夺键盘焦点。</strong></p><p>它不应影响鼠标点击其他应用、全屏游戏、IDE 输入或正常窗口操作。</p><h3 id="_3-2-l1-悬浮-quick-panel" tabindex="-1">3.2 L1：悬浮 Quick Panel <a class="header-anchor" href="#_3-2-l1-悬浮-quick-panel" aria-label="Permalink to &quot;3.2 L1：悬浮 Quick Panel&quot;">​</a></h3><p>这是 Beacon 的核心界面。</p><p>点击状态胶囊或按全局快捷键 <code>Ctrl+Alt+B</code> 后，显示一个紧凑的悬浮面板。</p><p>推荐布局：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────┐</span></span>
<span class="line"><span>│ Beacon                         ⚙  × │</span></span>
<span class="line"><span>│                                     │</span></span>
<span class="line"><span>│ 需要关注                         2  │</span></span>
<span class="line"><span>│ ─────────────────────────────────── │</span></span>
<span class="line"><span>│ ● Client Build                     │</span></span>
<span class="line"><span>│   构建失败 · 3 分钟前                │</span></span>
<span class="line"><span>│   [查看详情] [重试]                  │</span></span>
<span class="line"><span>│                                     │</span></span>
<span class="line"><span>│ ◐ Backend Build                    │</span></span>
<span class="line"><span>│   构建中 · 已运行 4 分钟             │</span></span>
<span class="line"><span>│                                     │</span></span>
<span class="line"><span>│ ● Pull Requests                    │</span></span>
<span class="line"><span>│   1 个 PR 等待处理                   │</span></span>
<span class="line"><span>│                                     │</span></span>
<span class="line"><span>│ ─────────────────────────────────── │</span></span>
<span class="line"><span>│ 最近状态更新 · 20 秒前               │</span></span>
<span class="line"><span>└─────────────────────────────────────┘</span></span></code></pre></div><p>以上为示意布局，不代表真实数据。</p><p>面板只需要三个信息区域：</p><ol><li><p><strong>需要关注</strong>：失败、超时或需要人工处理的事项。</p></li><li><p><strong>正在运行</strong>：当前重要任务。</p></li><li><p><strong>最近状态</strong>：必要的成功、状态变化或待处理事项。</p></li></ol><p>不需要把所有 Widget、仓库和统计数据都放在首页。</p><h4 id="交互规则" tabindex="-1">交互规则 <a class="header-anchor" href="#交互规则" aria-label="Permalink to &quot;交互规则&quot;">​</a></h4><ul><li><p>点击事件打开详情。</p></li><li><p>有明确且安全的操作时才显示操作按钮。</p></li><li><p>失败任务可以提供查看详情、重试等操作。</p></li><li><p>普通成功任务优先提供跳转，而不是增加一组管理按钮。</p></li><li><p>点击外部或按 ESC 可以关闭面板。</p></li><li><p>点击面板内部时不应因为失焦事件导致面板立即关闭。</p></li><li><p>操作执行期间保留必要的进度反馈。</p></li><li><p>操作完成后更新状态，不假设操作已经成功。</p></li><li><p>刷新失败时展示最后更新时间，而不是清空原有状态。</p></li></ul><p>建议初始尺寸约为 360–420 DIP 宽、420–560 DIP 高。实际高度根据内容动态调整，并设置最大高度和滚动区域。</p><blockquote><p><strong>已拍板落地（2026-10-11 批3-补27④）</strong>：三分区以 NEEDS ATTENTION / RUNNING / RECENT EVENTS 实现 （RECENT EVENTS 即「最近状态」，OVERVIEW 计数与通知中心保留），初始宽 <strong>380 DIP</strong>（带内取中）； 「需要关注」判定 = Warning 及以上 / 数据过期 / 连接断（Core <code>QuickPanelSections</code>，10 例单测）。</p></blockquote><p>面板应支持 Windows 缩放、多显示器、任务栏位置变化和屏幕边缘约束。</p><h3 id="_3-3-l2-详情" tabindex="-1">3.3 L2：详情 <a class="header-anchor" href="#_3-3-l2-详情" aria-label="Permalink to &quot;3.3 L2：详情&quot;">​</a></h3><p>不需要为每个数据源开发完整的详情管理系统。</p><p>详情只显示当前事项必要的信息：</p><ul><li><p>名称和来源。</p></li><li><p>当前状态。</p></li><li><p>开始时间与耗时。</p></li><li><p>分支、仓库或任务标识。</p></li><li><p>可获取的错误摘要。</p></li><li><p>最近更新时间。</p></li><li><p>可执行的少量操作。</p></li><li><p>打开原始详情的链接。</p></li></ul><p>如果原始平台已经拥有完整日志、诊断信息或操作界面，应直接跳转到原始平台。</p><p><strong>L2 的职责是解释状态，不是复制原平台。</strong></p><h3 id="_3-4-系统托盘" tabindex="-1">3.4 系统托盘 <a class="header-anchor" href="#_3-4-系统托盘" aria-label="Permalink to &quot;3.4 系统托盘&quot;">​</a></h3><p>托盘用于生命周期管理和全局设置。</p><p>建议菜单：</p><ul><li><p>打开 Beacon。</p></li><li><p>刷新状态。</p></li><li><p>连接与数据源设置。</p></li><li><p>通知设置。</p></li><li><p>关于 Beacon。</p></li><li><p>退出。</p></li></ul><p>不在托盘菜单中堆放所有任务操作。</p><h3 id="_3-5-快捷键" tabindex="-1">3.5 快捷键 <a class="header-anchor" href="#_3-5-快捷键" aria-label="Permalink to &quot;3.5 快捷键&quot;">​</a></h3><p>默认全局快捷键为 <code>Ctrl+Alt+B</code>。</p><p>要求：</p><ul><li><p>可以在设置中关闭或更改。</p></li><li><p>注册失败时明确提示，不影响应用启动。</p></li><li><p>快捷键冲突不能导致应用崩溃。</p></li><li><p>重复按下时应切换面板的显示状态，而不是创建多个窗口。</p></li></ul><h3 id="_3-6-默认形态-2026-10-11-拍板修订" tabindex="-1">3.6 默认形态（2026-10-11 拍板修订） <a class="header-anchor" href="#_3-6-默认形态-2026-10-11-拍板修订" aria-label="Permalink to &quot;3.6 默认形态（2026-10-11 拍板修订）&quot;">​</a></h3><p>不默认把桌面铺成「多独立窗口小仪表盘」：<strong>默认形态是单宿主面板</strong>（每显示器一个透明置顶宿主窗，单窗多 tile， RFC §6.2.4），桌面常驻物至多叠加：状态胶囊（默认关）、快捷面板（按呼出）、详情窗（按需）。</p><p><strong>用户令优先于本方案原稿</strong>（2026-10-11 用户令「数量悬浮窗默认开 状态胶囊默认关」）：数量/额度类钉选组件 默认以独立悬浮框上桌（<code>numericFloatingEnabled=true</code>，设置可关=桌面零残留）；胶囊默认关（<code>showCapsule=false</code>）。 独立悬浮框形态（每组件一窗）是用户显式选择（设置「悬浮形态」二选一，重启生效），不随安装默认整体铺开—— 原稿「只留胶囊+面板+详情」据此修订，窗口管理复杂度顾虑由「panel 默认 + floating 须显式切换 + 准入策略 （信息密度门槛）」化解。</p><p>原因是它会增加窗口管理、布局配置、拖动、显示器适配和状态同步的复杂度，也容易让桌面变成一块小型仪表盘。</p><hr><h2 id="_4-技术架构" tabindex="-1">4. 技术架构 <a class="header-anchor" href="#_4-技术架构" aria-label="Permalink to &quot;4. 技术架构&quot;">​</a></h2><h3 id="_4-1-总体架构" tabindex="-1">4.1 总体架构 <a class="header-anchor" href="#_4-1-总体架构" aria-label="Permalink to &quot;4.1 总体架构&quot;">​</a></h3><p>采用单进程、模块化的 Windows 桌面应用。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Beacon.App</span></span>
<span class="line"><span>├── Tray / Hotkey</span></span>
<span class="line"><span>├── Status Capsule</span></span>
<span class="line"><span>├── Quick Panel</span></span>
<span class="line"><span>├── Detail View</span></span>
<span class="line"><span>└── Settings</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>Beacon.Core</span></span>
<span class="line"><span>├── State Aggregator</span></span>
<span class="line"><span>├── Refresh Scheduler</span></span>
<span class="line"><span>├── Event Lifecycle</span></span>
<span class="line"><span>├── Notification Policy</span></span>
<span class="line"><span>├── Action Dispatcher</span></span>
<span class="line"><span>└── Domain Models</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ├── Beacon.Connections</span></span>
<span class="line"><span>        │   ├── GitHub</span></span>
<span class="line"><span>        │   └── Company Build</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ├── Beacon.Actions</span></span>
<span class="line"><span>        │   ├── Open URL</span></span>
<span class="line"><span>        │   └── Supported Provider Actions</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        └── Beacon.Storage</span></span>
<span class="line"><span>            ├── Local Configuration</span></span>
<span class="line"><span>            ├── State Cache</span></span>
<span class="line"><span>            └── Secure Credential References</span></span></code></pre></div><p>AI Usage Provider 可以在未来以同样的方式接入，但不影响第一版发布。</p><h3 id="_4-2-技术选型" tabindex="-1">4.2 技术选型 <a class="header-anchor" href="#_4-2-技术选型" aria-label="Permalink to &quot;4.2 技术选型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>选择</th></tr></thead><tbody><tr><td>编程语言</td><td>C#</td></tr><tr><td>桌面 UI</td><td>WinUI 3</td></tr><tr><td>运行时</td><td>.NET 10</td></tr><tr><td>架构</td><td>MVVM + 模块化 Core</td></tr><tr><td>配置</td><td>JSON</td></tr><tr><td>凭据</td><td>Windows DPAPI 或 Windows Credential Manager</td></tr><tr><td>测试</td><td>现有测试框架与项目规范</td></tr><tr><td>CI</td><td>GitHub Actions，Windows Runner</td></tr><tr><td>发布</td><td>安装包与便携包</td></tr><tr><td>后端</td><td>无</td></tr><tr><td>数据库</td><td>第一版不需要数据库</td></tr></tbody></table><p>如果现有项目已经采用其他成熟的内部抽象，应优先复用，而不是为了符合文档名称而大规模重构。</p><h3 id="_4-3-核心架构原则" tabindex="-1">4.3 核心架构原则 <a class="header-anchor" href="#_4-3-核心架构原则" aria-label="Permalink to &quot;4.3 核心架构原则&quot;">​</a></h3><p><strong>UI 不直接请求远端数据源。</strong></p><p>所有状态刷新统一经过 Core 调度和 Provider 接口。</p><p><strong>Provider 只负责数据适配。</strong></p><p>Provider 将外部系统的数据转换为统一领域模型，不负责窗口展示、托盘颜色和通知弹窗。</p><p><strong>Action Dispatcher 只执行有限的原子操作。</strong></p><p>它不是脚本执行器或任务编排系统。</p><p><strong>Storage 只保存必要信息。</strong></p><p>配置、凭据引用、必要的状态缓存和轻量历史足够支撑产品。</p><p><strong>不增加后台服务进程。</strong></p><p>除非后续有明确、不可替代的技术需求，否则保持单进程架构。</p><hr><h2 id="_5-核心领域模型" tabindex="-1">5. 核心领域模型 <a class="header-anchor" href="#_5-核心领域模型" aria-label="Permalink to &quot;5. 核心领域模型&quot;">​</a></h2><h3 id="_5-1-severity" tabindex="-1">5.1 Severity <a class="header-anchor" href="#_5-1-severity" aria-label="Permalink to &quot;5.1 Severity&quot;">​</a></h3><p>全产品使用统一严重程度：</p><ul><li><p><code>Info</code></p></li><li><p><code>Success</code></p></li><li><p><code>Warning</code></p></li><li><p><code>Error</code></p></li><li><p><code>Critical</code></p></li></ul><p>离线和刷新失败应通过连接健康状态与数据新鲜度表达，不应简单地把所有网络异常都映射成 Critical。</p><h3 id="_5-2-lifecyclestate" tabindex="-1">5.2 LifecycleState <a class="header-anchor" href="#_5-2-lifecyclestate" aria-label="Permalink to &quot;5.2 LifecycleState&quot;">​</a></h3><p>任务生命周期：</p><ul><li><p><code>Queued</code></p></li><li><p><code>Running</code></p></li><li><p><code>Success</code></p></li><li><p><code>Failed</code></p></li><li><p><code>Cancelled</code></p></li><li><p><code>Skipped</code></p></li><li><p><code>Unknown</code></p></li></ul><p>外部 Provider 必须将源系统的状态映射到统一枚举。</p><h3 id="_5-3-widgetstate" tabindex="-1">5.3 WidgetState <a class="header-anchor" href="#_5-3-widgetstate" aria-label="Permalink to &quot;5.3 WidgetState&quot;">​</a></h3><p>每个状态项至少包含：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>WidgetState</span></span>
<span class="line"><span>├── Id</span></span>
<span class="line"><span>├── ProviderId</span></span>
<span class="line"><span>├── Title</span></span>
<span class="line"><span>├── Severity</span></span>
<span class="line"><span>├── LifecycleState</span></span>
<span class="line"><span>├── Summary</span></span>
<span class="line"><span>├── DetailUrl</span></span>
<span class="line"><span>├── UpdatedAt</span></span>
<span class="line"><span>├── LastSuccessfulFetchAt</span></span>
<span class="line"><span>├── IsStale</span></span>
<span class="line"><span>└── ConnectionHealth</span></span></code></pre></div><p>详细错误信息和外部响应不应无限制地保存在状态对象中。</p><h3 id="_5-4-activity" tabindex="-1">5.4 Activity <a class="header-anchor" href="#_5-4-activity" aria-label="Permalink to &quot;5.4 Activity&quot;">​</a></h3><p>Activity 用于表达值得关注的状态变化，而不是每次轮询都生成一条事件。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Activity</span></span>
<span class="line"><span>├── Id</span></span>
<span class="line"><span>├── SourceId</span></span>
<span class="line"><span>├── SubjectId</span></span>
<span class="line"><span>├── Kind</span></span>
<span class="line"><span>├── Severity</span></span>
<span class="line"><span>├── Summary</span></span>
<span class="line"><span>├── OccurredAt</span></span>
<span class="line"><span>├── FirstSeenAt</span></span>
<span class="line"><span>├── LastSeenAt</span></span>
<span class="line"><span>├── AcknowledgedAt</span></span>
<span class="line"><span>└── Fingerprint</span></span></code></pre></div><p>事件去重应基于稳定标识或指纹，而不是只比较显示文本。</p><p>第一版只需要支持：</p><ul><li><p>新事件。</p></li><li><p>已查看或已确认。</p></li><li><p>已解决。</p></li><li><p>同一事件更新时合并。</p></li></ul><p>不建设复杂的事件编排、工作流或事件分析引擎。</p><blockquote><p>落地状态（2026-10-11 审计补记）：<code>Activity</code>/<code>Fingerprint</code> 未作为一等类型实现（src 全域零命中）。 当前以三段现有机制承载其语义：<code>NotificationRecord</code>（notifications.json 落盘，含 <code>read</code> 已读态，滚动保留 200 条）</p><ul><li><code>NotificationEngine</code> 去重（阈值跨越语义 = 同一段 Warning 只提醒一次，或时间冷却）</li><li><code>RecentEvent</code>（L2 面板会话内事件流，无持久化）。指纹级去重未实现，事件合并未实现——待真机验收后排期。</li></ul></blockquote><h3 id="_5-5-provider-接口" tabindex="-1">5.5 Provider 接口 <a class="header-anchor" href="#_5-5-provider-接口" aria-label="Permalink to &quot;5.5 Provider 接口&quot;">​</a></h3><p>继续沿用现有 Provider 抽象，概念上提供：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>public interface IWidgetProvider</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    string Id { get; }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    Task&lt;WidgetState&gt; GetStateAsync(</span></span>
<span class="line"><span>        WidgetConfig config,</span></span>
<span class="line"><span>        CancellationToken cancellationToken);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>实际接口以仓库现有实现为准，不要因为示例而重复定义。</p><p>每个 Provider 还应明确：</p><ul><li><p>支持哪些状态。</p></li><li><p>支持哪些操作。</p></li><li><p>推荐刷新间隔。</p></li><li><p>认证方式。</p></li><li><p>失败后的重试策略。</p></li><li><p>数据是否可能过期。</p></li></ul><p>Provider 可以是内置模块，不需要动态程序集加载或插件发现机制。</p><hr><h2 id="_6-状态刷新与通知" tabindex="-1">6. 状态刷新与通知 <a class="header-anchor" href="#_6-状态刷新与通知" aria-label="Permalink to &quot;6. 状态刷新与通知&quot;">​</a></h2><h3 id="_6-1-刷新机制" tabindex="-1">6.1 刷新机制 <a class="header-anchor" href="#_6-1-刷新机制" aria-label="Permalink to &quot;6.1 刷新机制&quot;">​</a></h3><p>采用缓存优先、后台刷新。</p><p>打开面板时：</p><ol><li><p>立即显示最后一次有效状态。</p></li><li><p>在后台执行必要的刷新。</p></li><li><p>获取结果后增量更新 UI。</p></li><li><p>如果刷新失败，保留旧状态并标记过期。</p></li></ol><p>不要让打开面板的操作等待所有网络请求完成。</p><h3 id="_6-2-刷新频率" tabindex="-1">6.2 刷新频率 <a class="header-anchor" href="#_6-2-刷新频率" aria-label="Permalink to &quot;6.2 刷新频率&quot;">​</a></h3><p>刷新间隔按 Provider 和接口限额调整，不设置一个全局固定的高频轮询。</p><p>初始建议：</p><ul><li><p>PR：60–120 秒。</p></li><li><p>CI 状态：20–60 秒。</p></li><li><p>公司打包工具：依据实际接口能力，初始可采用 15–30 秒。</p></li><li><p>AI 额度：依据来源的更新频率，通常不需要高频查询。</p></li></ul><p>这些是初始策略，不是固定承诺。</p><p>必须实现：</p><ul><li><p>请求取消。</p></li><li><p>同一数据源避免重复并发刷新。</p></li><li><p>失败退避。</p></li><li><p>请求超时。</p></li><li><p>GitHub ETag / 条件请求。</p></li><li><p>GitHub Rate Limit 感知。</p></li><li><p>应用恢复后刷新。</p></li><li><p>网络不可用时保留缓存。</p></li></ul><h3 id="_6-3-通知策略" tabindex="-1">6.3 通知策略 <a class="header-anchor" href="#_6-3-通知策略" aria-label="Permalink to &quot;6.3 通知策略&quot;">​</a></h3><p>通知只用于值得打断用户的事件：</p><ul><li><p>构建失败。</p></li><li><p>重要任务从运行中变为失败。</p></li><li><p>关键状态发生变化。</p></li><li><p>用户明确配置的阈值触发。</p></li></ul><p>默认不通知：</p><ul><li><p>每次刷新。</p></li><li><p>每次轮询。</p></li><li><p>普通成功状态。</p></li><li><p>没有实质变化的重复失败。</p></li><li><p>可通过胶囊安静展示的常规运行状态。</p></li></ul><p>同一事件应去重。用户已确认的事件在没有实质状态变化时不应反复提醒。</p><p>通知内容应包含来源、事件摘要和打开详情的入口。</p><p>通知点击后必须定位到对应事件，不能只打开一个没有上下文的首页。</p><hr><h2 id="_7-操作执行与安全" tabindex="-1">7. 操作执行与安全 <a class="header-anchor" href="#_7-操作执行与安全" aria-label="Permalink to &quot;7. 操作执行与安全&quot;">​</a></h2><h3 id="_7-1-允许的操作" tabindex="-1">7.1 允许的操作 <a class="header-anchor" href="#_7-1-允许的操作" aria-label="Permalink to &quot;7.1 允许的操作&quot;">​</a></h3><p>第一版只提供必要操作：</p><ul><li><p>打开原始详情。</p></li><li><p>刷新状态。</p></li><li><p>重试受支持的任务。</p></li><li><p>执行来源平台提供的简单、明确操作。</p></li></ul><p>不提供任意 shell、PowerShell、批处理脚本执行功能。</p><blockquote><p><strong>例外（2026-10-11 拍板③）</strong>：已落地的 <code>local.command</code> Action 保留——默认<strong>执行前确认弹窗</strong>、命令在设置中 明文可见、带超时与输出捕获（RFC §13）。它不是脚本执行平台（无编排/无批量/无编辑器），是 mission 原案 [Build][Test][Deploy] 快捷动作的承载。不再扩展脚本能力；新操作类型一律按「来源平台提供的简单、明确操作」原则评审。</p></blockquote><h3 id="_7-2-操作结果" tabindex="-1">7.2 操作结果 <a class="header-anchor" href="#_7-2-操作结果" aria-label="Permalink to &quot;7.2 操作结果&quot;">​</a></h3><p>每个 Action 应返回明确结果：</p><ul><li><p><code>Succeeded</code></p></li><li><p><code>Failed</code></p></li><li><p><code>Cancelled</code></p></li><li><p><code>TimedOut</code></p></li><li><p><code>Unsupported</code></p></li></ul><p>执行请求成功提交，不等于底层任务执行成功。</p><p>例如 GitHub 接受重跑请求后，Beacon 应显示已提交重跑请求，并继续刷新实际运行状态。</p><h3 id="_7-3-凭据安全" tabindex="-1">7.3 凭据安全 <a class="header-anchor" href="#_7-3-凭据安全" aria-label="Permalink to &quot;7.3 凭据安全&quot;">​</a></h3><ul><li><p>普通 JSON 只保存凭据引用。</p></li><li><p>Token 使用 DPAPI 或 Windows Credential Manager 保护。</p></li><li><p>日志不得包含完整 Token、Authorization Header 或敏感响应。</p></li><li><p>设置界面不得在普通文本框中回显已保存的完整凭据。</p></li><li><p>不需要管理员权限运行。</p></li><li><p>不需要开放本地监听端口。</p></li><li><p>不建立远程控制通道。</p></li></ul><p>GitHub Token 应遵循最小权限原则。需要写操作时才申请相应写权限，纯状态读取优先使用只读权限。</p><h3 id="_7-4-失败隔离" tabindex="-1">7.4 失败隔离 <a class="header-anchor" href="#_7-4-失败隔离" aria-label="Permalink to &quot;7.4 失败隔离&quot;">​</a></h3><p>一个 Provider 失败，不应影响其他 Provider 或桌面 UI。</p><p>网络错误、认证失败、权限不足、限额耗尽和服务端错误应有不同的用户提示。</p><p>错误日志应支持定位问题，但不记录秘密信息。</p><hr><h2 id="_8-本地配置与数据存储" tabindex="-1">8. 本地配置与数据存储 <a class="header-anchor" href="#_8-本地配置与数据存储" aria-label="Permalink to &quot;8. 本地配置与数据存储&quot;">​</a></h2><p>沿用现有配置体系，避免新增不必要的存储技术。</p><p>建议将用户数据保存在 <code>%AppData%\\Beacon\\</code> 下。</p><p>逻辑上包括：</p><ul><li><p><code>config.json</code>：全局设置。</p></li><li><p><code>connections.json</code>：连接信息和凭据引用。</p></li><li><p><code>widgets.json</code>：需要展示的状态项。</p></li><li><p><code>cache.json</code>：必要的轻量状态缓存。</p></li><li><p><code>history.json</code>：有限的事件历史。</p></li></ul><p>如果当前仓库已经存在不同的配置文件划分，不必强行改名。重点是保持职责清晰，并提供向后兼容的配置迁移。</p><blockquote><p>落地状态（2026-10-11 审计补记）：实际文件划分与上表逻辑名不同，按「不必强行改名」执行—— <code>%AppData%\\Beacon\\</code> 下 <code>config.json</code>（全局设置）、<code>connections.json</code>、<code>widgets.json</code>、<code>pins.json</code>、<code>actions.json</code>、 <code>notifications.json</code>（本方案无对应逻辑名；已读态落盘，滚动 200 条）、<code>cache\\{connId}\\states.json</code>（缓存按连接分目录，非 cache.json）、 <code>secrets.bin</code>（DPAPI 密钥，唯一密钥落点）。损坏原件留档 <code>*.corrupt</code> 并记录 <code>LoadErrors</code>，不阻断启动。</p></blockquote><p>要求：</p><ul><li><p>文件写入采用安全的原子替换策略。</p></li><li><p>配置损坏时能给出明确提示。</p></li><li><p>首次启动自动创建默认配置。</p></li><li><p>不存在的可选配置使用默认值。</p></li><li><p>无效配置不能导致整个应用无法启动。</p></li><li><p>事件历史有上限，并定期清理旧数据。</p></li></ul><p>第一版不需要 SQLite。只有当真实使用证明 JSON 在查询、并发写入或历史容量方面无法满足需求时，才重新评估。</p><hr><h2 id="_9-windows-桌面体验与生命周期" tabindex="-1">9. Windows 桌面体验与生命周期 <a class="header-anchor" href="#_9-windows-桌面体验与生命周期" aria-label="Permalink to &quot;9. Windows 桌面体验与生命周期&quot;">​</a></h2><p>必须覆盖以下场景：</p><ul><li><p>单实例启动。</p></li><li><p>托盘图标创建和销毁。</p></li><li><p>开机自启。</p></li><li><p>用户主动退出。</p></li><li><p>悬浮窗口显示与隐藏。</p></li><li><p>ESC 关闭面板。</p></li><li><p>全局热键注册与冲突。</p></li><li><p>高 DPI 与多显示器。</p></li><li><p>显示器断开或分辨率变化。</p></li><li><p>Explorer 重启后恢复托盘图标。</p></li><li><p>锁屏、解锁与系统睡眠恢复。</p></li><li><p>网络断开与恢复。</p></li><li><p>应用异常退出后的诊断。</p></li></ul><p>悬浮窗口应尽可能使用原生 Windows 能力实现，不引入 WebView 或其他 UI 框架来重复实现桌面外壳。</p><p>需要特别验证窗口不会无意抢焦点、无法关闭或跑到屏幕外。</p><p>开机自启应允许用户关闭。安装和卸载过程不应要求管理员权限，除非 Windows 系统本身或特定安装方式另有要求。</p><hr><h2 id="_10-设置界面" tabindex="-1">10. 设置界面 <a class="header-anchor" href="#_10-设置界面" aria-label="Permalink to &quot;10. 设置界面&quot;">​</a></h2><p>设置只保留四类内容：</p><h3 id="通用" tabindex="-1">通用 <a class="header-anchor" href="#通用" aria-label="Permalink to &quot;通用&quot;">​</a></h3><ul><li><p>开机自启。</p></li><li><p>全局快捷键。</p></li><li><p>胶囊显示与位置。</p></li><li><p>面板行为。</p></li><li><p>退出行为。</p></li></ul><h3 id="连接" tabindex="-1">连接 <a class="header-anchor" href="#连接" aria-label="Permalink to &quot;连接&quot;">​</a></h3><ul><li><p>GitHub 连接。</p></li><li><p>公司打包工具连接。</p></li><li><p>凭据管理。</p></li><li><p>连接测试。</p></li><li><p>数据源启用或禁用。</p></li></ul><h3 id="通知" tabindex="-1">通知 <a class="header-anchor" href="#通知" aria-label="Permalink to &quot;通知&quot;">​</a></h3><ul><li><p>是否启用通知。</p></li><li><p>失败通知。</p></li><li><p>阈值设置。</p></li><li><p>静默或合并重复通知。</p></li></ul><h3 id="关于" tabindex="-1">关于 <a class="header-anchor" href="#关于" aria-label="Permalink to &quot;关于&quot;">​</a></h3><ul><li><p>版本信息。</p></li><li><p>日志位置。</p></li><li><p>开源许可证。</p></li><li><p>检查更新或打开项目主页。</p></li></ul><p>不要设置独立的插件管理器、命令管理器或复杂规则编辑器。</p><blockquote><p>落地状态（2026-10-11 审计补记；2026-10-14 增量复核更新计数）：通用（胶囊/面板/外观/热键/自启/检查频率）、连接（GitHub + HTTP 通用 + 12 家 AI 额度（含 2026-10-13 商汤 SenseNova Token Plan 积分池）+ 凭据 + 连接测试 + 模块启停，共 17 类，含 Jenkins/本机/Herald）、通知（规则/阈值/冷却去重）均已落地；公司打包工具槽位由 Jenkins Provider 落位（开源标准 JSON API，任意实例可配）。 「关于」现有版本行（InformationalVersion）与日志位置提示；开源许可证、检查更新/项目主页入口（2026-10-12 批3-补46/47 已补齐，见下）。 （2026-10-12 批3-补46 已补齐：「关于」增 Apache-2.0 许可证行 + 项目主页/检查更新（nightly 下载页）入口， 系统浏览器打开、失败落运行日志。2026-10-12 批3-补47 再补真比较：三行 = 当前版本/远程最新版本/检查结果 （GitHub releases/latest 与本地 InformationalVersion 比，Core 纯函数 SemVer 比较；启动 20s 自检一次并缓存， 手动按钮强刷；断网/超时/非 200 一律「无法检查更新 + 时间」不弹异常框；有新版本时给「打开下载页」按钮。 版本口径：csproj Version 为唯一权威基准，daily-build 发布时注入日期版本 + SHA 滚 nightly tag（--latest=false）； 仓库无正式发版 workflow，正式发版 tag 注入待用户首次令发版时建。） 「退出行为」在托盘 Exit（唯一退出路径），不在设置页。</p></blockquote><hr><h2 id="_11-测试策略" tabindex="-1">11. 测试策略 <a class="header-anchor" href="#_11-测试策略" aria-label="Permalink to &quot;11. 测试策略&quot;">​</a></h2><h3 id="_11-1-单元测试" tabindex="-1">11.1 单元测试 <a class="header-anchor" href="#_11-1-单元测试" aria-label="Permalink to &quot;11.1 单元测试&quot;">​</a></h3><p>覆盖：</p><ul><li><p>状态映射。</p></li><li><p>严重程度聚合。</p></li><li><p>事件指纹和去重。</p></li><li><p>状态过期。</p></li><li><p>通知规则。</p></li><li><p>刷新调度。</p></li><li><p>请求取消。</p></li><li><p>Action 执行结果。</p></li><li><p>配置读写和迁移。</p></li><li><p>凭据引用。</p></li><li><p>GitHub 限额处理。</p></li></ul><h3 id="_11-2-集成测试" tabindex="-1">11.2 集成测试 <a class="header-anchor" href="#_11-2-集成测试" aria-label="Permalink to &quot;11.2 集成测试&quot;">​</a></h3><p>覆盖：</p><ul><li><p>GitHub API 响应映射。</p></li><li><p>Token 无效和权限不足。</p></li><li><p>API 限额耗尽。</p></li><li><p>网络超时。</p></li><li><p>Provider 部分失败。</p></li><li><p>旧缓存显示。</p></li><li><p>重试操作的完整生命周期。</p></li><li><p>数据源恢复后状态重新同步。</p></li></ul><p>公司打包工具应提供可重复使用的测试样本或模拟响应，避免每次测试都依赖真实公司环境。</p><h3 id="_11-3-windows-真机测试" tabindex="-1">11.3 Windows 真机测试 <a class="header-anchor" href="#_11-3-windows-真机测试" aria-label="Permalink to &quot;11.3 Windows 真机测试&quot;">​</a></h3><p>必须在 Windows 机器上验证：</p><ul><li><p>安装包安装、启动、卸载。</p></li><li><p>便携包启动。</p></li><li><p>托盘和悬浮面板。</p></li><li><p>快捷键。</p></li><li><p>多显示器与缩放。</p></li><li><p>通知点击。</p></li><li><p>开机自启。</p></li><li><p>Explorer 重启。</p></li><li><p>系统睡眠与唤醒。</p></li><li><p>应用关闭后不残留意外后台进程。</p></li></ul><h3 id="_11-4-干净环境测试" tabindex="-1">11.4 干净环境测试 <a class="header-anchor" href="#_11-4-干净环境测试" aria-label="Permalink to &quot;11.4 干净环境测试&quot;">​</a></h3><p>在没有预先安装开发环境的 Windows 虚拟机中测试发布包。</p><p>验证自包含运行时、缺失依赖提示、配置初始化、凭据存储、日志生成和升级行为。</p><p>CI 构建通过不等于产品验收通过。</p><hr><h2 id="_12-性能与质量目标" tabindex="-1">12. 性能与质量目标 <a class="header-anchor" href="#_12-性能与质量目标" aria-label="Permalink to &quot;12. 性能与质量目标&quot;">​</a></h2><p>以下作为首版工程目标，而不是未经测量的性能承诺。</p><ul><li><p>启动后尽快出现托盘和胶囊，不等待所有网络请求。</p></li><li><p>打开 Quick Panel 时优先显示缓存，避免明显的空白等待。</p></li><li><p>空闲状态下尽量降低 CPU 占用和网络请求。</p></li><li><p>不持续高频刷新所有数据源。</p></li><li><p>一个连接超时不能冻结 UI。</p></li><li><p>长时间运行不应不断积累事件、窗口或后台任务。</p></li><li><p>关闭面板不应导致整个应用退出。</p></li><li><p>退出应用后不应残留意外进程。</p></li><li><p>任何凭据都不得进入日志或普通配置文件。</p></li></ul><p>性能验收应通过实际测量记录，而不是仅根据代码推测。</p><hr><h2 id="_13-实施计划" tabindex="-1">13. 实施计划 <a class="header-anchor" href="#_13-实施计划" aria-label="Permalink to &quot;13. 实施计划&quot;">​</a></h2><p>当前仓库已经完成部分核心模块，因此采用增量实施，不从零搭建。</p><h3 id="m0-范围冻结与现状核对" tabindex="-1">M0：范围冻结与现状核对 <a class="header-anchor" href="#m0-范围冻结与现状核对" aria-label="Permalink to &quot;M0：范围冻结与现状核对&quot;">​</a></h3><ul><li><p>以本方案更新 <code>docs/mission.md</code>。</p></li><li><p>更新 <code>docs/rfc/RFC-001-technical-design.md</code>。</p></li><li><p>对照现有实现检查状态胶囊、Quick Panel、Provider 和 Action 的真实行为。</p></li><li><p>删除与本方案冲突的未来规划。</p></li><li><p>记录尚未完成的真实环境验证。</p></li></ul><p>验收：产品范围与代码实施计划一致。</p><h3 id="m1-桌面-shell" tabindex="-1">M1：桌面 Shell <a class="header-anchor" href="#m1-桌面-shell" aria-label="Permalink to &quot;M1：桌面 Shell&quot;">​</a></h3><p>复用现有托盘、单实例、快捷键、开机自启和窗口生命周期实现。</p><p>验收：桌面入口稳定，不抢焦点，不产生重复窗口。</p><h3 id="m2-core-状态机制" tabindex="-1">M2：Core 状态机制 <a class="header-anchor" href="#m2-core-状态机制" aria-label="Permalink to &quot;M2：Core 状态机制&quot;">​</a></h3><p>复用现有刷新调度、状态聚合、缓存、事件总线和通知规则。</p><p>验收：缓存优先、增量更新、状态过期和错误隔离正常。</p><h3 id="m3-github" tabindex="-1">M3：GitHub <a class="header-anchor" href="#m3-github" aria-label="Permalink to &quot;M3：GitHub&quot;">​</a></h3><p>复用现有 PR、Actions Provider 和限额感知实现。</p><p>验收：真实数据可读取、状态映射准确、失败通知去重、跳转和重试行为正确。</p><h3 id="m4-quick-panel" tabindex="-1">M4：Quick Panel <a class="header-anchor" href="#m4-quick-panel" aria-label="Permalink to &quot;M4：Quick Panel&quot;">​</a></h3><p>重点完成悬浮面板的视觉和交互：</p><ul><li><p>需要关注。</p></li><li><p>正在运行。</p></li><li><p>最近状态。</p></li><li><p>必要的上下文操作。</p></li><li><p>错误和离线提示。</p></li><li><p>面板关闭与焦点行为。</p></li></ul><p>验收：面板小巧、信息清晰，用户不必打开浏览器就能理解发生了什么。</p><h3 id="m5-发布与验收" tabindex="-1">M5：发布与验收 <a class="header-anchor" href="#m5-发布与验收" aria-label="Permalink to &quot;M5：发布与验收&quot;">​</a></h3><ul><li><p>Windows 真机走查。</p></li><li><p>干净虚拟机安装验证。</p></li><li><p>安装包与便携包验证。</p></li><li><p>日志和故障排查验证。</p></li><li><p>性能与长时间运行测试。</p></li><li><p>更新 README 与安装说明。</p></li></ul><p>验收：不依赖开发机环境即可正常安装、启动和使用。</p><h3 id="后续可选-公司打包工具-provider" tabindex="-1">后续可选：公司打包工具 Provider <a class="header-anchor" href="#后续可选-公司打包工具-provider" aria-label="Permalink to &quot;后续可选：公司打包工具 Provider&quot;">​</a></h3><blockquote><p>落地状态（2026-10-11 批3-补31）：该槽位由 <strong>Jenkins Provider</strong>（<code>jenkins.build</code> + <code>jenkins</code> 连接） 以开源标准 JSON API 落位——任意实例可配，凭据匿名或 <code>user:apiToken</code>，Folder 路径转义，一次请求按 <code>color</code> 判级。下文「取得真实 API 后再接入」口径仍适用于<strong>厂商私有打包工具</strong>（非开源标准 API 需按其 实际接口评估，不建设常驻 Agent 或远程控制系统）。</p></blockquote><p>（本项已关闭：Jenkins Provider 已按开源标准 JSON API 落位——见上「落地状态」注；厂商私有打包工具按其实际接口评估，不建设常驻 Agent 或远程控制系统。）</p><h3 id="后续可选-ai-usage-provider-2026-10-11-批3-补41-评估收口-已关闭" tabindex="-1">后续可选：AI Usage Provider（2026-10-11 批3-补41 评估收口，已关闭） <a class="header-anchor" href="#后续可选-ai-usage-provider-2026-10-11-批3-补41-评估收口-已关闭" aria-label="Permalink to &quot;后续可选：AI Usage Provider（2026-10-11 批3-补41 评估收口，已关闭）&quot;">​</a></h3><p>仅在数据来源可靠、维护成本合理时实现；不能为了支持更多服务商而影响核心桌面体验和维护成本。</p><blockquote><p>落地状态（2026-10-11 批3-补41 评估收口）：<strong>条件已满足且早已超出——本项关闭</strong>。本项写入时是条件门控占位； 此后 positioning P0 #5 将 AI Usage 提为首发 P0，2026-10-08 起逐家落地 <strong>13 种组件类型/11 家</strong> （bigmodel/ark/claude/kimi/deepseek/mimo/codex/copilot/opencode/qwen/moonshot + http.status/quota 通用面）。 数据源可靠性三档：① 官方稳定 API 六家（deepseek /v1/users/me/balance、moonshot balance、bigmodel 监控 quota/limit、ark 管控面 OpenAPI V4 签名、copilot 官方扩展同款配额端点、opencode Console Budgets——key 长效无会话态）； ② 本机零网络两家（claude/codex 读本机会话 jsonl，绝对可靠零维护，codex 标注非官方口径）； ③ 会话 cookie 两家（kimi/mimo 控制台口，端点稳定但会话过期是常态——401 明示+重录指引在卡面）+ qwen 官方额度口未开放（如实降级链：自定义端点→配额探针→模型目录，不造数）。 维护成本实测：两次形状漂移（kimi F-50、mimo F-51）均被「单文件多类 + 防御解析 fail-loud + 如实降级」 隔离、当日收口；刷新失败不清缓存（§14.5），单家漂移不伤核心桌面体验。残余维护面 = 两家 cookie 偶发重录（用户侧动作，有指引）。</p></blockquote><hr><h2 id="_14-mvp-验收标准" tabindex="-1">14. MVP 验收标准 <a class="header-anchor" href="#_14-mvp-验收标准" aria-label="Permalink to &quot;14. MVP 验收标准&quot;">​</a></h2><p>Beacon 第一版只有满足以下条件才算完成：</p><ol><li><p>Windows 登录后能够按用户设置启动。</p></li><li><p>托盘和状态胶囊可以稳定运行。</p></li><li><p>全局快捷键能正常打开悬浮面板。</p></li><li><p>面板能够展示真实 GitHub 状态。</p></li><li><p>Provider 刷新失败时不会清空有效缓存。</p></li><li><p>重要失败事件能够触发通知，重复事件不会持续打扰用户。</p></li><li><p>用户能够查看详情或跳转原始平台。</p></li><li><p>支持的操作有明确的执行结果反馈。</p></li><li><p>凭据得到安全保存，日志中不存在明文秘密。</p></li><li><p>安装包和便携包能够在干净 Windows 环境运行。</p></li><li><p>没有意外后台进程、明显资源泄漏或窗口生命周期问题。</p></li><li><p>核心体验不依赖独立后端服务。</p></li></ol><p>公司打包工具的集成可以作为紧随 MVP 的重要里程碑，但必须基于真实接口进行验收，不能用模拟数据代替真实集成结果。</p><hr><h2 id="_15-给-code-agent-的实施约束" tabindex="-1">15. 给 Code Agent 的实施约束 <a class="header-anchor" href="#_15-给-code-agent-的实施约束" aria-label="Permalink to &quot;15. 给 Code Agent 的实施约束&quot;">​</a></h2><p>开始修改代码前，必须先阅读：</p><ul><li><p><code>README.md</code></p></li><li><p><code>docs/mission.md</code></p></li><li><p><code>docs/rfc/RFC-001-technical-design.md</code></p></li><li><p><code>docs/solution-structure.md</code></p></li><li><p><code>docs/mvp-issues.md</code></p></li></ul><p>随后检查当前源码和测试，列出现有实现、缺失功能、重复抽象和与本方案冲突的部分。</p><p>实施要求：</p><ol><li><p>复用现有成熟实现，不重写已经完成的模块。</p></li><li><p>不因为本方案中的示例代码而重复定义已有接口。</p></li><li><p>不引入数据库、后端服务、脚本执行器、复杂插件系统或工作流引擎。</p></li><li><p>不新增未经验证的外部依赖。</p></li><li><p>不用模拟数据宣称真实集成已完成。</p></li><li><p>每次修改都必须配套测试或说明无法自动化验证的原因。</p></li><li><p>更新文档中的功能状态，不能把待真机验证的功能标记为完全验收。</p></li><li><p>优先解决窗口交互、状态准确性、资源占用和错误处理。</p></li><li><p>如果现有架构与本方案冲突，先提交差异分析和最小改造建议，不直接进行大规模重构。</p></li><li><p>所有新增功能都必须符合 Beacon 的轻量定位。</p></li></ol><h2 id="_16-最终产品定义" tabindex="-1">16. 最终产品定义 <a class="header-anchor" href="#_16-最终产品定义" aria-label="Permalink to &quot;16. 最终产品定义&quot;">​</a></h2><p>Beacon 是一个小巧、常驻、可靠的 Windows 开发者状态中心。</p><p>它的核心体验是：</p><p><strong>托盘感知状态 → 胶囊提醒异常 → 悬浮面板解释问题 → 简单操作或跳转原始工具。</strong></p><p>它不需要成为开发者的万能控制台，也不需要接管其他工具的工作。</p><p>成功标准不是功能数量，而是用户每天开发时几乎感觉不到它的存在，却能在真正需要关注的问题出现时及时发现并快速处理。</p><p><strong>产品原则：Keep it small. Stay useful. Never get in the way.</strong></p><h2 id="附-落地路径-2026-10-11-用户附言" tabindex="-1">附：落地路径（2026-10-11 用户附言） <a class="header-anchor" href="#附-落地路径-2026-10-11-用户附言" aria-label="Permalink to &quot;附：落地路径（2026-10-11 用户附言）&quot;">​</a></h2><p>先不立即大规模改代码：先对照本方案与当前仓库做一次差异审计——尤其核对现有 RFC 中的多 Widget 固定布局、 Quick Panel 交互、Provider 边界和当前 M5 验收状态——之后只修改真正冲突的部分。最大限度复用已完成的 M1–M5 工作，不为新方案再制造一轮重构。</p>`,274)])])}const b=p(n,[["render",s]]);export{u as __pageData,b as default};
